-- GreenSolutions 4.0.1 — Ajuda da transação Administração › Guia do usuário.
-- Grava a ajuda em guniversal_dbp.ajuda_transacoes (padrão do portal, editável em
-- Configurações › Ajuda das transações). Só insere quando ainda não existe, para
-- não sobrescrever ajustes feitos pela tela de ajuda.
-- HTML restrito às tags aceitas pelo editor de ajuda (p, h2, ul, ol, li, strong, em, a).
SET NAMES utf8mb4 COLLATE utf8mb4_0900_ai_ci;

INSERT INTO ajuda_transacoes (transacao, titulo_pt, titulo_en, titulo_es, texto_pt, texto_en, texto_es, ativo)
SELECT 'administracao_guia_usuario',
       'Ajuda — Guia do usuário (administração)', 'Help — User guide (administration)', 'Ayuda — Guía del usuario (administración)',
       '<p>Nesta tela o <strong>ADMINISTRADOR</strong> mantém o conteúdo do <strong>Guia do usuário</strong>, que todos abrem pelo ícone do livro no canto superior direito. O guia é <strong>único para todas as empresas</strong>: o que for publicado aqui aparece para os usuários de todas elas.</p><p>O trabalho é feito em duas etapas: você altera um <strong>rascunho</strong>, que só você e os outros administradores veem, e depois <strong>publica</strong>. Enquanto não publicar, os usuários continuam vendo a versão anterior.</p><h2>1. Como a tela está organizada</h2><ul><li><strong>Barra superior:</strong> botões Salvar rascunho, Pré-visualizar, Publicar, Versões e Ajuda.</li><li><strong>Linha de situação:</strong> mostra a versão publicada vigente (número, data e quem publicou) e uma etiqueta com o estado do rascunho.</li><li><strong>Estrutura do guia (à esquerda):</strong> a árvore com os Perfis e as Abas. Clique em um item para editá-lo. Os botões com <strong>+</strong> incluem itens novos.</li><li><strong>Formulário (à direita):</strong> os campos do item selecionado e, no alto, os botões para mover, duplicar e excluir.</li></ul><h2>2. O que significam as etiquetas de situação</h2><ul><li><strong>Alterações não salvas</strong> (vermelha): você mudou algo e ainda não salvou. Se fechar a aba agora, perde as alterações.</li><li><strong>Rascunho com alterações não publicadas</strong> (laranja): o rascunho está salvo, mas é diferente do que os usuários veem. Falta publicar.</li><li><strong>Rascunho igual ao publicado</strong> (verde): não há nada pendente.</li><li><strong>Somente leitura</strong>: seu perfil pode consultar a tela, mas apenas o ADMINISTRADOR altera o guia.</li></ul><h2>3. Roteiro rápido para alterar o guia</h2><ol><li>Na árvore, clique no item que deseja mudar (por exemplo, uma etapa do fluxo).</li><li>Com o idioma <strong>PT</strong> selecionado, ajuste os textos.</li><li>Troque para <strong>EN</strong> e <strong>ES</strong> e preencha as traduções.</li><li>Clique em <strong>Salvar rascunho</strong> (ou use <strong>Ctrl+S</strong>).</li><li>Clique em <strong>Pré-visualizar</strong> e confira o resultado como o usuário verá.</li><li>Clique em <strong>Publicar</strong>, escreva o que mudou e confirme.</li></ol><h2>4. As partes do guia</h2><ul><li><strong>Perfis:</strong> os papéis que aparecem no filtro "Ver etapas de" e na etiqueta de cada etapa (Administrador, Responsável, Aprovador…). O perfil <strong>sistema</strong> é usado nas etapas automáticas e não pode ser excluído.</li><li><strong>Abas (módulos):</strong> cada aba do guia, por exemplo Módulo Legal e Homologação de Fornecedores.</li><li><strong>Fluxo do processo:</strong> a primeira parte de cada aba. É dividido em <strong>fases</strong> numeradas, e cada fase tem <strong>etapas</strong>.</li><li><strong>Como fazer:</strong> passo a passo curto de tarefas comuns, mostrado em blocos que abrem ao clicar.</li><li><strong>Onde encontrar:</strong> o caminho no menu e para que serve cada tela.</li><li><strong>Termos e dicas:</strong> pequenos cartões com o significado de palavras do sistema. Um termo marcado como dica aparece com destaque verde.</li></ul><h2>5. Editar uma etapa do fluxo</h2><ul><li><strong>Quem executa:</strong> escolha <strong>M — Manual</strong> quando a pessoa faz a etapa, ou <strong>A — Automático</strong> quando o sistema faz sozinho (alertas, cálculos, tarefas geradas). Ao escolher A, o perfil passa a ser Sistema automaticamente.</li><li><strong>Perfil:</strong> quem faz a etapa. Os perfis da aba aparecem primeiro na lista.</li><li><strong>Título:</strong> uma ação curta, de preferência começando com verbo (ex.: "Registrar a situação de atendimento").</li><li><strong>Descrição:</strong> uma ou duas frases simples explicando o que fazer.</li><li><strong>Onde:</strong> o caminho no menu ou o botão que o usuário deve clicar (ex.: "Requisitos legais › botão Situação").</li></ul><p>Dica de escrita: o guia foi pensado para ser lido rapidamente. Prefira frases curtas e evite repetir no texto o que já está no título.</p><h2>6. Trabalhar com os três idiomas</h2><ul><li>O seletor <strong>PT | EN | ES</strong> no alto do formulário define em qual idioma você está escrevendo. Ele vale para todos os campos de texto do item.</li><li>Ao editar EN ou ES, o texto em português aparece logo abaixo de cada campo como referência.</li><li>O número laranja sobre EN ou ES indica quantas traduções faltam naquele item. Na árvore, um <strong>ponto laranja</strong> marca itens com tradução pendente.</li><li>Se um campo ficar vazio em EN ou ES, o usuário verá o texto em português. Isso não impede a publicação, mas o ideal é traduzir tudo.</li></ul><h2>7. Criar uma nova aba</h2><ol><li>Em <strong>Abas (módulos)</strong>, clique em <strong>+ Nova aba</strong> e informe um código (ex.: <em>nao-conformidades</em>). Use de 2 a 40 letras minúsculas, números, hífen ou sublinhado.</li><li>A aba nasce <strong>oculta</strong>, para que você possa montá-la com calma sem que os usuários a vejam.</li><li>Preencha nome, resumo e ícone e marque os <strong>perfis desta aba</strong> (eles formam o filtro "Ver etapas de").</li><li>Monte o fluxo: use <strong>+ Fase</strong> para criar fases e <strong>+ Etapa</strong> dentro de cada fase. Depois inclua Como fazer, Onde encontrar e Termos.</li><li>Quando estiver pronta, ligue a chave <strong>Aba visível para os usuários</strong>, salve e publique.</li></ol><p>O código da aba também pode ser usado para abrir o guia direto nela, com o endereço <em>guia_usuario.php?modulo=código</em>.</p><h2>8. Perfis</h2><ul><li>Use <strong>+ Novo perfil</strong> e informe um código (ex.: <em>comprador</em>). O código não pode ser alterado depois; o nome e o ícone podem.</li><li>Um perfil só pode ser excluído quando não estiver em uso em nenhuma etapa nem marcado em nenhuma aba. Troque-o antes nesses lugares.</li><li>Os perfis do guia são apenas rótulos explicativos. Eles <strong>não</strong> alteram permissões de acesso do sistema.</li></ul><h2>9. Organizar, duplicar e excluir</h2><ul><li>As setas <strong>↑</strong> e <strong>↓</strong> mudam a ordem do item dentro do grupo (abas, fases, etapas, passos etc.).</li><li><strong>Duplicar</strong> cria uma cópia logo abaixo, útil para criar itens parecidos. Uma aba duplicada nasce oculta e com o código terminado em "-copia".</li><li><strong>Excluir</strong> remove o item do rascunho. Para os usuários, a exclusão só vale depois de publicar. Se excluir por engano, use Versões para recuperar.</li><li>Nos itens de <strong>Como fazer</strong>, cada passo tem as próprias setas e o botão de remover; use <strong>Adicionar passo</strong> para incluir um novo.</li></ul><h2>10. Ícones</h2><p>Escolha um dos ícones sugeridos com um clique ou digite o nome de um ícone do Bootstrap Icons, sempre começando com <em>bi-</em> (ex.: <em>bi-truck</em>). A lista completa está em <a href="https://icons.getbootstrap.com/">icons.getbootstrap.com</a>. Se o nome não existir, o ícone aparece em branco.</p><h2>11. Salvar, pré-visualizar e publicar</h2><ul><li><strong>Salvar rascunho</strong> grava suas alterações sem mostrá-las aos usuários. Salve com frequência. Se você tentar sair da tela com alterações não salvas, o navegador avisa.</li><li><strong>Pré-visualizar</strong> salva o rascunho e abre o guia exatamente como ficará, com uma faixa amarela indicando que é uma pré-visualização. Somente quem tem acesso a esta tela consegue ver o rascunho.</li><li><strong>Publicar</strong> transforma o rascunho em uma nova versão, que passa a valer para todos. Você pode escrever o que mudou; isso fica no histórico.</li></ul><p>Antes de publicar, o sistema confere se as abas visíveis têm nome em português e se fases, etapas, "Como fazer" e termos têm título. Se faltar algo, aparece uma lista do que corrigir. Abas ocultas não são conferidas, para não atrapalhar quem está montando uma aba nova. Também não é possível publicar um rascunho igual à versão vigente.</p><h2>12. Versões</h2><ul><li>O botão <strong>Versões</strong> mostra todas as publicações, com data, autor e observação. A versão em uso aparece como <strong>vigente</strong>.</li><li><strong>Ver</strong> abre a versão escolhida para consulta.</li><li><strong>Restaurar no rascunho</strong> copia aquela versão para o rascunho. Ela só volta a valer para os usuários depois de publicar.</li><li><strong>Descartar rascunho e voltar ao publicado</strong> apaga as alterações do rascunho que ainda não foram publicadas.</li><li>As versões publicadas nunca são alteradas nem apagadas, por isso é sempre possível voltar atrás.</li></ul><h2>13. Dois administradores ao mesmo tempo</h2><p>Se outro administrador salvar o rascunho enquanto você edita, ao salvar você verá o aviso de que o rascunho foi alterado. Isso evita que um apague o trabalho do outro. Copie o texto que você estava escrevendo, recarregue a tela e aplique sua alteração sobre a versão mais recente.</p><h2>14. Dúvidas frequentes</h2><ul><li><strong>Publiquei, mas o usuário ainda vê o texto antigo.</strong> Peça para ele fechar o guia e abrir de novo pelo ícone do livro.</li><li><strong>A aba nova não aparece para os usuários.</strong> Confira se a chave "Aba visível para os usuários" está ligada e se você publicou depois disso.</li><li><strong>O botão Publicar diz que não há nada para publicar.</strong> O rascunho está igual à versão vigente; não há alterações.</li><li><strong>Publiquei algo errado.</strong> Em Versões, restaure a versão anterior no rascunho e publique de novo.</li><li><strong>Os botões e títulos fixos do guia</strong> (Buscar, Legenda, Manual/Automático) não são editados aqui; eles fazem parte do sistema.</li></ul><h2>15. Link direto para a tela</h2><p>Etapas do fluxo, itens de "Como fazer" e itens de "Onde encontrar" podem ter um <strong>Link direto para a tela</strong>. No guia, aparece o botão <strong>Abrir tela</strong>: ao clicar, a transação abre em uma aba do portal, como se o usuário tivesse usado o menu, e o guia se fecha.</p><ul><li>Escolha a tela na lista do campo <strong>Link direto para a tela</strong>. A lista mostra as transações ativas do menu, agrupadas pelo menu principal. Para tirar o link, escolha "Sem link".</li><li>O botão só aparece para quem tem permissão de acessar aquela tela. Quem não tem permissão vê apenas o texto, sem o botão.</li><li>Na árvore, o ícone de corrente indica os itens que têm link.</li><li>Se aparecer o aviso de que a transação não existe ou está inativa, o menu foi alterado: escolha outra tela ou retire o link.</li><li>Use o link quando ele economizar tempo de verdade, normalmente nas etapas manuais. Etapas automáticas raramente precisam de link.</li></ul><p>Esta ajuda pode ser ajustada em <strong>Configurações › Ajuda das transações</strong>, transação <em>administracao_guia_usuario</em>.</p>',
       '<p>On this screen the <strong>ADMINISTRADOR</strong> maintains the content of the <strong>User guide</strong>, which everyone opens through the book icon in the upper-right corner. The guide is <strong>the same for all companies</strong>: whatever is published here is shown to the users of every company.</p><p>The work has two stages: you change a <strong>draft</strong>, seen only by you and the other administrators, and then you <strong>publish</strong> it. Until you publish, users keep seeing the previous version.</p><h2>1. How the screen is organized</h2><ul><li><strong>Top bar:</strong> Save draft, Preview, Publish, Versions and Help buttons.</li><li><strong>Status line:</strong> shows the current published version (number, date and who published it) and a label with the draft status.</li><li><strong>Guide structure (left):</strong> the tree with Profiles and Tabs. Click an item to edit it. The <strong>+</strong> buttons add new items.</li><li><strong>Form (right):</strong> the fields of the selected item and, at the top, the buttons to move, duplicate and delete it.</li></ul><h2>2. What the status labels mean</h2><ul><li><strong>Unsaved changes</strong> (red): you changed something and have not saved it yet. If you close the tab now, the changes are lost.</li><li><strong>Draft has unpublished changes</strong> (orange): the draft is saved but differs from what users see. It still needs to be published.</li><li><strong>Draft matches the published guide</strong> (green): nothing is pending.</li><li><strong>Read only</strong>: your profile can view the screen, but only the ADMINISTRADOR profile changes the guide.</li></ul><h2>3. Quick path to change the guide</h2><ol><li>In the tree, click the item you want to change (for example, a step of the flow).</li><li>With the <strong>PT</strong> language selected, adjust the texts.</li><li>Switch to <strong>EN</strong> and <strong>ES</strong> and fill in the translations.</li><li>Click <strong>Save draft</strong> (or press <strong>Ctrl+S</strong>).</li><li>Click <strong>Preview</strong> and check the result as users will see it.</li><li>Click <strong>Publish</strong>, describe what changed and confirm.</li></ol><h2>4. The parts of the guide</h2><ul><li><strong>Profiles:</strong> the roles shown in the "Show steps for" filter and in the label of each step (Administrator, Responsible, Approver…). The <strong>sistema</strong> profile is used in automatic steps and cannot be deleted.</li><li><strong>Tabs (modules):</strong> each tab of the guide, for example Legal Module and Supplier Homologation.</li><li><strong>Process flow:</strong> the first part of each tab. It is divided into numbered <strong>phases</strong>, and each phase has <strong>steps</strong>.</li><li><strong>How to:</strong> short step-by-step instructions for common tasks, shown in blocks that open on click.</li><li><strong>Where to find:</strong> the menu path and the purpose of each screen.</li><li><strong>Terms and tips:</strong> small cards explaining system words. A term marked as a tip is highlighted in green.</li></ul><h2>5. Editing a flow step</h2><ul><li><strong>Who performs it:</strong> choose <strong>M — Manual</strong> when a person performs the step, or <strong>A — Automatic</strong> when the system does it on its own (alerts, calculations, generated tasks). When you choose A, the profile is set to System automatically.</li><li><strong>Profile:</strong> who performs the step. The profiles of the tab appear first in the list.</li><li><strong>Title:</strong> a short action, preferably starting with a verb (e.g. "Record the compliance status").</li><li><strong>Description:</strong> one or two simple sentences explaining what to do.</li><li><strong>Where:</strong> the menu path or the button the user must click (e.g. "Legal requirements › Status button").</li></ul><p>Writing tip: the guide is meant to be read quickly. Prefer short sentences and do not repeat in the text what the title already says.</p><h2>6. Working with the three languages</h2><ul><li>The <strong>PT | EN | ES</strong> selector at the top of the form sets the language you are writing in. It applies to all text fields of the item.</li><li>When editing EN or ES, the Portuguese text is shown below each field as a reference.</li><li>The orange number on EN or ES shows how many translations are missing in that item. In the tree, an <strong>orange dot</strong> marks items with pending translations.</li><li>If a field is left empty in EN or ES, users see the Portuguese text. This does not block publishing, but it is best to translate everything.</li></ul><h2>7. Creating a new tab</h2><ol><li>Under <strong>Tabs (modules)</strong>, click <strong>+ New tab</strong> and enter a code (e.g. <em>non-conformities</em>). Use 2 to 40 lowercase letters, numbers, hyphens or underscores.</li><li>The tab is created <strong>hidden</strong>, so you can build it calmly without users seeing it.</li><li>Fill in name, summary and icon, and tick the <strong>profiles of this tab</strong> (they make up the "Show steps for" filter).</li><li>Build the flow: use <strong>+ Phase</strong> to create phases and <strong>+ Step</strong> inside each phase. Then add How to, Where to find and Terms.</li><li>When it is ready, turn on <strong>Tab visible to users</strong>, save and publish.</li></ol><p>The tab code can also be used to open the guide directly on that tab, with the address <em>guia_usuario.php?modulo=code</em>.</p><h2>8. Profiles</h2><ul><li>Use <strong>+ New profile</strong> and enter a code (e.g. <em>buyer</em>). The code cannot be changed later; the name and icon can.</li><li>A profile can only be deleted when it is not used in any step and not ticked in any tab. Replace it in those places first.</li><li>Guide profiles are only explanatory labels. They do <strong>not</strong> change system access permissions.</li></ul><h2>9. Ordering, duplicating and deleting</h2><ul><li>The <strong>↑</strong> and <strong>↓</strong> arrows change the order of the item within its group (tabs, phases, steps etc.).</li><li><strong>Duplicate</strong> creates a copy right below, useful for similar items. A duplicated tab is created hidden, with a code ending in "-copia".</li><li><strong>Delete</strong> removes the item from the draft. For users, the deletion only takes effect after publishing. If you delete something by mistake, use Versions to recover it.</li><li>In <strong>How to</strong> items, each step has its own arrows and remove button; use <strong>Add step</strong> to include a new one.</li></ul><h2>10. Icons</h2><p>Pick one of the suggested icons with a click or type the name of a Bootstrap Icons icon, always starting with <em>bi-</em> (e.g. <em>bi-truck</em>). The full list is at <a href="https://icons.getbootstrap.com/">icons.getbootstrap.com</a>. If the name does not exist, the icon is shown blank.</p><h2>11. Saving, previewing and publishing</h2><ul><li><strong>Save draft</strong> stores your changes without showing them to users. Save often. If you try to leave the screen with unsaved changes, the browser warns you.</li><li><strong>Preview</strong> saves the draft and opens the guide exactly as it will look, with a yellow bar indicating it is a preview. Only people with access to this screen can see the draft.</li><li><strong>Publish</strong> turns the draft into a new version that applies to everyone. You can describe what changed; this is kept in the history.</li></ul><p>Before publishing, the system checks that visible tabs have a Portuguese name and that phases, steps, How to items and terms have a title. If something is missing, a list of what to fix is shown. Hidden tabs are not checked, so they do not get in the way of someone building a new tab. A draft identical to the current version cannot be published.</p><h2>12. Versions</h2><ul><li>The <strong>Versions</strong> button lists all publications with date, author and note. The version in use is marked as <strong>current</strong>.</li><li><strong>View</strong> opens the chosen version for reference.</li><li><strong>Restore to draft</strong> copies that version into the draft. It only applies to users again after publishing.</li><li><strong>Discard draft and go back to published</strong> removes the draft changes that have not been published yet.</li><li>Published versions are never changed or deleted, so it is always possible to go back.</li></ul><h2>13. Two administrators at the same time</h2><p>If another administrator saves the draft while you are editing, when you save you will see a message saying the draft was changed. This prevents one person from overwriting the work of another. Copy the text you were writing, reload the screen and apply your change on top of the latest version.</p><h2>14. Frequently asked questions</h2><ul><li><strong>I published, but a user still sees the old text.</strong> Ask them to close the guide and open it again through the book icon.</li><li><strong>The new tab does not appear to users.</strong> Check that "Tab visible to users" is turned on and that you published after that.</li><li><strong>Publish says there is nothing to publish.</strong> The draft is identical to the current version; there are no changes.</li><li><strong>I published something wrong.</strong> In Versions, restore the previous version to the draft and publish again.</li><li><strong>The fixed buttons and headings of the guide</strong> (Search, Legend, Manual/Automatic) are not edited here; they are part of the system.</li></ul><h2>15. Direct link to the screen</h2><p>Flow steps, How to items and Where to find items can have a <strong>Direct link to the screen</strong>. In the guide, an <strong>Open screen</strong> button is shown: when clicked, the transaction opens in a portal tab, as if the user had used the menu, and the guide closes.</p><ul><li>Choose the screen in the <strong>Direct link to the screen</strong> list. It shows the active menu transactions, grouped by main menu. To remove the link, choose "No link".</li><li>The button only appears for users allowed to access that screen. Users without permission see only the text.</li><li>In the tree, the chain icon marks items that have a link.</li><li>If a warning says the transaction does not exist or is inactive, the menu was changed: choose another screen or remove the link.</li><li>Use links when they really save time, usually in manual steps. Automatic steps rarely need a link.</li></ul><p>This help can be adjusted in <strong>Settings › Transaction help</strong>, transaction <em>administracao_guia_usuario</em>.</p>',
       '<p>En esta pantalla el <strong>ADMINISTRADOR</strong> mantiene el contenido de la <strong>Guía del usuario</strong>, que todos abren con el ícono del libro en la esquina superior derecha. La guía es <strong>única para todas las empresas</strong>: lo que se publique aquí aparece para los usuarios de todas ellas.</p><p>El trabajo se hace en dos etapas: usted modifica un <strong>borrador</strong>, que solo ven usted y los demás administradores, y después lo <strong>publica</strong>. Mientras no publique, los usuarios siguen viendo la versión anterior.</p><h2>1. Cómo está organizada la pantalla</h2><ul><li><strong>Barra superior:</strong> botones Guardar borrador, Vista previa, Publicar, Versiones y Ayuda.</li><li><strong>Línea de estado:</strong> muestra la versión publicada vigente (número, fecha y quién la publicó) y una etiqueta con el estado del borrador.</li><li><strong>Estructura de la guía (a la izquierda):</strong> el árbol con los Perfiles y las Pestañas. Haga clic en un ítem para editarlo. Los botones con <strong>+</strong> agregan ítems nuevos.</li><li><strong>Formulario (a la derecha):</strong> los campos del ítem seleccionado y, arriba, los botones para mover, duplicar y eliminar.</li></ul><h2>2. Qué significan las etiquetas de estado</h2><ul><li><strong>Cambios sin guardar</strong> (roja): usted cambió algo y todavía no lo guardó. Si cierra la pestaña ahora, pierde los cambios.</li><li><strong>Borrador con cambios no publicados</strong> (naranja): el borrador está guardado, pero es distinto de lo que ven los usuarios. Falta publicar.</li><li><strong>Borrador igual al publicado</strong> (verde): no hay nada pendiente.</li><li><strong>Solo lectura</strong>: su perfil puede consultar la pantalla, pero solo el ADMINISTRADOR modifica la guía.</li></ul><h2>3. Recorrido rápido para modificar la guía</h2><ol><li>En el árbol, haga clic en el ítem que desea cambiar (por ejemplo, una etapa del flujo).</li><li>Con el idioma <strong>PT</strong> seleccionado, ajuste los textos.</li><li>Cambie a <strong>EN</strong> y <strong>ES</strong> y complete las traducciones.</li><li>Haga clic en <strong>Guardar borrador</strong> (o use <strong>Ctrl+S</strong>).</li><li>Haga clic en <strong>Vista previa</strong> y revise el resultado tal como lo verá el usuario.</li><li>Haga clic en <strong>Publicar</strong>, escriba qué cambió y confirme.</li></ol><h2>4. Las partes de la guía</h2><ul><li><strong>Perfiles:</strong> los papeles que aparecen en el filtro "Ver etapas de" y en la etiqueta de cada etapa (Administrador, Responsable, Aprobador…). El perfil <strong>sistema</strong> se usa en las etapas automáticas y no puede eliminarse.</li><li><strong>Pestañas (módulos):</strong> cada pestaña de la guía, por ejemplo Módulo Legal y Homologación de Proveedores.</li><li><strong>Flujo del proceso:</strong> la primera parte de cada pestaña. Se divide en <strong>fases</strong> numeradas y cada fase tiene <strong>etapas</strong>.</li><li><strong>Cómo hacer:</strong> paso a paso corto de tareas comunes, en bloques que se abren con un clic.</li><li><strong>Dónde encontrar:</strong> la ruta en el menú y para qué sirve cada pantalla.</li><li><strong>Términos y consejos:</strong> pequeñas tarjetas con el significado de palabras del sistema. Un término marcado como consejo aparece destacado en verde.</li></ul><h2>5. Editar una etapa del flujo</h2><ul><li><strong>Quién lo ejecuta:</strong> elija <strong>M — Manual</strong> cuando la persona realiza la etapa, o <strong>A — Automático</strong> cuando el sistema lo hace solo (alertas, cálculos, tareas generadas). Al elegir A, el perfil pasa a ser Sistema automáticamente.</li><li><strong>Perfil:</strong> quién realiza la etapa. Los perfiles de la pestaña aparecen primero en la lista.</li><li><strong>Título:</strong> una acción corta, preferiblemente comenzando con un verbo (ej.: "Registrar la situación de cumplimiento").</li><li><strong>Descripción:</strong> una o dos frases simples que expliquen qué hacer.</li><li><strong>Dónde:</strong> la ruta del menú o el botón que el usuario debe usar (ej.: "Requisitos legales › botón Situación").</li></ul><p>Consejo de redacción: la guía fue pensada para leerse rápido. Prefiera frases cortas y no repita en el texto lo que ya dice el título.</p><h2>6. Trabajar con los tres idiomas</h2><ul><li>El selector <strong>PT | EN | ES</strong> en la parte superior del formulario define en qué idioma está escribiendo. Vale para todos los campos de texto del ítem.</li><li>Al editar EN o ES, el texto en portugués aparece debajo de cada campo como referencia.</li><li>El número naranja sobre EN o ES indica cuántas traducciones faltan en ese ítem. En el árbol, un <strong>punto naranja</strong> marca los ítems con traducción pendiente.</li><li>Si un campo queda vacío en EN o ES, el usuario verá el texto en portugués. Eso no impide publicar, pero lo ideal es traducir todo.</li></ul><h2>7. Crear una nueva pestaña</h2><ol><li>En <strong>Pestañas (módulos)</strong>, haga clic en <strong>+ Nueva pestaña</strong> e indique un código (ej.: <em>no-conformidades</em>). Use de 2 a 40 letras minúsculas, números, guion o guion bajo.</li><li>La pestaña nace <strong>oculta</strong>, para que pueda armarla con calma sin que los usuarios la vean.</li><li>Complete nombre, resumen e ícono y marque los <strong>perfiles de esta pestaña</strong> (forman el filtro "Ver etapas de").</li><li>Arme el flujo: use <strong>+ Fase</strong> para crear fases y <strong>+ Etapa</strong> dentro de cada fase. Después agregue Cómo hacer, Dónde encontrar y Términos.</li><li>Cuando esté lista, active <strong>Pestaña visible para los usuarios</strong>, guarde y publique.</li></ol><p>El código de la pestaña también sirve para abrir la guía directamente en ella, con la dirección <em>guia_usuario.php?modulo=código</em>.</p><h2>8. Perfiles</h2><ul><li>Use <strong>+ Nuevo perfil</strong> e indique un código (ej.: <em>comprador</em>). El código no se puede cambiar después; el nombre y el ícono sí.</li><li>Un perfil solo puede eliminarse cuando no está en uso en ninguna etapa ni marcado en ninguna pestaña. Cámbielo antes en esos lugares.</li><li>Los perfiles de la guía son solo etiquetas explicativas. <strong>No</strong> modifican los permisos de acceso del sistema.</li></ul><h2>9. Ordenar, duplicar y eliminar</h2><ul><li>Las flechas <strong>↑</strong> y <strong>↓</strong> cambian el orden del ítem dentro de su grupo (pestañas, fases, etapas, pasos, etc.).</li><li><strong>Duplicar</strong> crea una copia justo debajo, útil para crear ítems parecidos. Una pestaña duplicada nace oculta y con el código terminado en "-copia".</li><li><strong>Eliminar</strong> quita el ítem del borrador. Para los usuarios, la eliminación solo vale después de publicar. Si elimina algo por error, use Versiones para recuperarlo.</li><li>En los ítems de <strong>Cómo hacer</strong>, cada paso tiene sus propias flechas y botón de quitar; use <strong>Agregar paso</strong> para incluir uno nuevo.</li></ul><h2>10. Íconos</h2><p>Elija uno de los íconos sugeridos con un clic o escriba el nombre de un ícono de Bootstrap Icons, siempre comenzando con <em>bi-</em> (ej.: <em>bi-truck</em>). La lista completa está en <a href="https://icons.getbootstrap.com/">icons.getbootstrap.com</a>. Si el nombre no existe, el ícono aparece en blanco.</p><h2>11. Guardar, vista previa y publicar</h2><ul><li><strong>Guardar borrador</strong> graba sus cambios sin mostrarlos a los usuarios. Guarde con frecuencia. Si intenta salir de la pantalla con cambios sin guardar, el navegador le avisa.</li><li><strong>Vista previa</strong> guarda el borrador y abre la guía exactamente como quedará, con una franja amarilla que indica que es una vista previa. Solo quien tiene acceso a esta pantalla puede ver el borrador.</li><li><strong>Publicar</strong> convierte el borrador en una nueva versión, que pasa a valer para todos. Puede escribir qué cambió; eso queda en el historial.</li></ul><p>Antes de publicar, el sistema verifica que las pestañas visibles tengan nombre en portugués y que fases, etapas, ítems de Cómo hacer y términos tengan título. Si falta algo, aparece una lista de lo que hay que corregir. Las pestañas ocultas no se verifican, para no estorbar a quien está armando una pestaña nueva. Tampoco es posible publicar un borrador igual a la versión vigente.</p><h2>12. Versiones</h2><ul><li>El botón <strong>Versiones</strong> muestra todas las publicaciones, con fecha, autor y observación. La versión en uso aparece como <strong>vigente</strong>.</li><li><strong>Ver</strong> abre la versión elegida para consulta.</li><li><strong>Restaurar en el borrador</strong> copia esa versión al borrador. Solo vuelve a valer para los usuarios después de publicar.</li><li><strong>Descartar borrador y volver al publicado</strong> elimina los cambios del borrador que todavía no se publicaron.</li><li>Las versiones publicadas nunca se modifican ni se borran, por eso siempre es posible volver atrás.</li></ul><h2>13. Dos administradores al mismo tiempo</h2><p>Si otro administrador guarda el borrador mientras usted edita, al guardar verá el aviso de que el borrador fue modificado. Esto evita que uno borre el trabajo del otro. Copie el texto que estaba escribiendo, recargue la pantalla y aplique su cambio sobre la versión más reciente.</p><h2>14. Preguntas frecuentes</h2><ul><li><strong>Publiqué, pero el usuario todavía ve el texto anterior.</strong> Pídale que cierre la guía y la abra de nuevo con el ícono del libro.</li><li><strong>La pestaña nueva no aparece para los usuarios.</strong> Verifique que "Pestaña visible para los usuarios" esté activada y que haya publicado después de eso.</li><li><strong>Publicar dice que no hay nada para publicar.</strong> El borrador es igual a la versión vigente; no hay cambios.</li><li><strong>Publiqué algo equivocado.</strong> En Versiones, restaure la versión anterior en el borrador y publique de nuevo.</li><li><strong>Los botones y títulos fijos de la guía</strong> (Buscar, Leyenda, Manual/Automático) no se editan aquí; forman parte del sistema.</li></ul><h2>15. Enlace directo a la pantalla</h2><p>Las etapas del flujo, los ítems de Cómo hacer y los de Dónde encontrar pueden tener un <strong>Enlace directo a la pantalla</strong>. En la guía aparece el botón <strong>Abrir pantalla</strong>: al hacer clic, la transacción se abre en una pestaña del portal, como si el usuario hubiera usado el menú, y la guía se cierra.</p><ul><li>Elija la pantalla en la lista del campo <strong>Enlace directo a la pantalla</strong>. Muestra las transacciones activas del menú, agrupadas por el menú principal. Para quitar el enlace, elija "Sin enlace".</li><li>El botón solo aparece para quien tiene permiso de acceder a esa pantalla. Quien no tiene permiso ve solo el texto.</li><li>En el árbol, el ícono de cadena indica los ítems con enlace.</li><li>Si aparece el aviso de que la transacción no existe o está inactiva, el menú fue modificado: elija otra pantalla o quite el enlace.</li><li>Use el enlace cuando realmente ahorre tiempo, normalmente en las etapas manuales. Las etapas automáticas rara vez necesitan enlace.</li></ul><p>Esta ayuda puede ajustarse en <strong>Configuraciones › Ayuda de las transacciones</strong>, transacción <em>administracao_guia_usuario</em>.</p>',
       1
 WHERE NOT EXISTS (SELECT 1 FROM ajuda_transacoes WHERE transacao = 'administracao_guia_usuario');

INSERT INTO green_universal_migrations (codigo_migracao, versao, status, detalhes)
VALUES ('GREEN_GUIA_USUARIO_AJUDA_200', '4.0.1', 'CONCLUIDA', JSON_OBJECT('transacao', 'administracao_guia_usuario', 'tabela', 'ajuda_transacoes'))
ON DUPLICATE KEY UPDATE status = VALUES(status), detalhes = VALUES(detalhes), executado_em = CURRENT_TIMESTAMP;
